static uint32_t next_cp(const char **s){const unsigned char*p=(const unsigned char*)*s;uint32_t cp;if(!*p)return 0;if(*p<0x80){cp=*p;*s+=1;return cp;}if((*p&0xE0)==0xC0){cp=((p[0]&31)<<6)|(p[1]&63);*s+=2;return cp;}if((*p&0xF0)==0xE0){cp=((p[0]&15)<<12)|((p[1]&63)<<6)|(p[2]&63);*s+=3;return cp;}*s+=1;return '?';}
static const Glyph*g(uint32_t cp){if(cp>='a'&&cp<='z')cp-=32;for(int i=0;i<N;i++)if(GLYPHS[i].cp==cp)return &GLYPHS[i];return g('?');}
int pixel_font_measure(const char*t,int s){int w=0;const char*p=t;while(*p){uint32_t cp=next_cp(&p);if(cp=='\n')break;w+=6*s;}return w?w-s:0;}
int pixel_font_fit_scale(const char*t,int mw,int pref,int min){for(int s=pref;s>=min;s--)if(pixel_font_measure(t,s)<=mw)return s;return min;}
static void dcp(GraphicsContext*c,uint32_t cp,int x,int y,int s,GColor col){const Glyph*z=g(cp);graphics_context_set_fill_color(c,col);for(int r=0;r<7;r++)for(int q=0;q<5;q++)if(z->r[r]&(1<<(4-q)))graphics_fill_rect(c,GRect(x+q*s,y+r*s,s,s),0,GCornerNone);}
void pixel_font_draw(GraphicsContext*c,const char*t,GRect b,int s,GColor col,PixelAlign a){int w=pixel_font_measure(t,s),x=b.origin.x;if(a==PF_ALIGN_CENTER)x+=(b.size.w-w)/2;else if(a==PF_ALIGN_RIGHT)x+=b.size.w-w;int y=b.origin.y+(b.size.h-7*s)/2;const char*p=t;while(*p){uint32_t cp=next_cp(&p);if(cp=='\n')break;dcp(c,cp,x,y,s,col);x+=6*s;}}
void pixel_font_draw_wrapped(GraphicsContext*c,const char*t,GRect b,int s,GColor col,PixelAlign a,int gap){char line[96];int li=0,y=b.origin.y;const char*p=t;line[0]=0;while(1){const char*ws=p;uint32_t cp=next_cp(&p);bool end=cp==0,br=cp=='\n'||cp==' ';if(!end&&!br){const char*q=ws;while(q<p&&li<94)line[li++]=*q++;line[li]=0;}if(br||end){if(cp==' '&&li<94){line[li++]=' ';line[li]=0;}if(cp=='\n'||end||pixel_font_measure(line,s)>b.size.w){if(pixel_font_measure(line,s)>b.size.w&&li>1){line[--li]=0;p=ws;}while(li>0&&line[li-1]==' ')line[--li]=0;pixel_font_draw(c,line,GRect(b.origin.x,y,b.size.w,7*s),s,col,a);y+=7*s+gap;li=0;line[0]=0;if(y+7*s>b.origin.y+b.size.h)return;}if(end)return;}}}
